-module(bright_hub_view).
-export([render/0,login/0]).
head(Title,Script) -> [<<"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>">>,Title,
 <<" &middot; Bright Studio</title><link rel='stylesheet' href='/studio/hub.css'><script defer src='">>,Script,<<"'></script>">>,evidence_script(Script),study_script(Script),<<"</head><body><a class='skip' href='#main'>Skip to content</a>">>,development_notice()].
development_notice()->case os:getenv("BRIGHT_SQLITE_DEVELOPMENT") of
    "true"-><<"<p class='development-notice' role='note'>Development demo: saved data can reset when the server restarts. Keep a copy of anything you need.</p>">>;
    _-><<>>
end.
evidence_script(<<"/studio/login.js">>)-><<>>;
evidence_script(_)->case bright_evidence:enabled() of true-><<"<script defer src='/studio/hub/evidence.js'></script>">>;false-><<>> end.
study_script(<<"/studio/login.js">>)-><<>>;
study_script(_)->case bright_study:enabled() of true-><<"<script defer src='/studio/hub/study.js'></script>">>;false-><<>> end.
login() -> [head(<<"Sign in">>,<<"/studio/login.js">>),
 <<"<main id='main' class='login'><p class='eyebrow'>Bright Studio</p><h1>Sign in</h1><p>Open your learning workspace.</p><form id='login-form'><label>Email<input name='email' type='email' autocomplete='username' required maxlength='254'></label><label>Password<input name='password' type='password' autocomplete='current-password' required maxlength='1024'></label><button>Sign in</button><p id='status' role='status' aria-live='polite'></p></form></main></body></html>">>].
render() -> [head(<<"Learning Hub">>,<<"/studio/hub/hub.js">>),
 <<"<div class='layout'><aside><a class='brand' href='/studio/hub/'>bright studio</a><nav aria-label='Primary'><a href='/studio/hub/'>Overview</a><a href='/studio/hub/library/'>Library</a><a id='evidence-nav' href='/studio/hub/evidence/' hidden>Evidence</a><a id='study-nav' href='/studio/hub/study/' hidden>Study</a><span>Focus &middot; Coming later</span><span>Documents &middot; Coming later</span><span>Audio &middot; Coming later</span></nav></aside><div><header><label>Project<select id='project' aria-label='Project'></select></label><span id='account'></span><button id='logout' class='secondary'>Sign out</button></header><main id='main'><p class='eyebrow'>Your learning workspace</p><h1 id='heading'>Library</h1><p id='description'>Keep the sources that matter, and return to them when you are ready.</p><p class='notice' id='library-notice'>Save source metadata now, or add a file to read it here.</p><p id='status' role='status' aria-live='polite'>Loading projects&hellip;</p><section id='library' hidden><div class='toolbar'><label>Search sources<input id='search' type='search'></label><button id='add'>Add Source</button></div><p id='empty' hidden>No sources yet. Add your first source to start your library.</p><div id='sources' class='grid'></div></section><section id='reader' hidden><a href='/studio/hub/library/'>Back to Library</a><h2 id='source-title'></h2><p id='source-kind'></p><a id='source-url' rel='noopener noreferrer' target='_blank' hidden>Open original link</a><p class='notice' id='metadata-only'>Reader placeholder. Only source metadata is saved; content has not been extracted.</p><section id='reading' hidden aria-label='Reading'><div class='toolbar'><label>Revision<select id='revision' aria-label='Revision'></select></label><a id='download' href='#'>Download original</a><button id='upload-revision' type='button'>Upload a revision</button></div><p id='reading-status' role='status' aria-live='polite'></p><button id='retry' type='button' hidden>Retry extraction</button><a id='study-source' hidden>Study this revision</a><article id='reading-text' aria-label='Source text'></article></section><section id='evidence-panel' hidden aria-label='Evidence and notes'><h2>Evidence and notes</h2><p>Select text in the Reader, then capture it. Or enter an exact quote below to find its location using the keyboard.</p><button id='capture-selection' type='button' disabled>Capture selected text</button><label>Find a quote<textarea id='find-quote' rows='2' maxlength='2048'></textarea></label><button id='find-selection' type='button' disabled class='secondary'>Find quote</button><p id='evidence-status' role='status'></p><div id='evidence-list'></div></section><button id='first-upload' type='button' hidden>Upload a file</button></section><section id='boards-page' hidden aria-label='Project evidence boards'><h2>Project boards</h2><form id='board-form'><label>Board title<input id='board-title' required maxlength='120'></label><button>Create board</button></form><p id='board-status' role='status'>Loading boards&hellip;</p><div id='board-list' class='grid'></div><section id='board-detail' hidden><h3 id='board-heading'></h3><div id='board-items'></div></section></section><section id='study-page' hidden aria-label='Study'><p>Practice missing-word recall from your saved sources. Each lesson covers up to six passages of 80 words (2,000 characters each). Answer each question, then save a reflection to finish.</p><p id='study-status' role='status' aria-live='polite'></p><button id='study-reload' class='secondary' type='button'>Refresh study</button><div id='study-picker' class='grid'></div><div id='study-passes' class='grid'></div><section id='study-lesson' hidden><h2 id='study-title'></h2><a id='study-origin'>Open pinned source revision</a><p id='study-progress'></p><details id='study-reference'><summary>Read the passage</summary><p id='study-text'></p></details><form id='study-form'><label id='study-prompt' for='study-answer'></label><textarea id='study-answer' required maxlength='2000' rows='4'></textarea><button id='study-submit'>Check answer</button></form><p id='study-feedback' role='status' aria-live='polite'></p><blockquote id='study-summary' hidden></blockquote><button id='study-back' type='button' class='secondary'>Back to lessons</button></section></section></main></div></div><dialog id='evidence-dialog' aria-labelledby='evidence-dialog-title'><form id='evidence-form'><h2 id='evidence-dialog-title'>Save evidence</h2><blockquote id='selected-quote'></blockquote><label>Evidence note<textarea id='evidence-note' rows='5' maxlength='4000'></textarea></label><p id='evidence-form-status' role='status'></p><div class='actions'><button id='evidence-cancel' type='button' class='secondary'>Cancel</button><button id='evidence-save'>Save evidence</button></div></form></dialog><dialog id='dialog' aria-labelledby='dialog-title'><form id='source-form'><h2 id='dialog-title'>Add Source</h2><p id='dialog-description'>Save a source to this project.</p><div id='metadata-fields'><label>Title<input name='title' required maxlength='200'></label><label>Type<select name='kind'><option value='note'>Note</option><option value='article'>Article</option><option value='book'>Book</option><option value='link'>Link</option></select></label><label>Original URL (optional)<input name='url' type='url' maxlength='2048' placeholder='https://'></label></div><label id='file-label' hidden>Source file (TXT, PDF or EPUB; up to 4 MiB)<input id='file' name='file' type='file' accept='.txt,.pdf,.epub,text/plain,application/pdf,application/epub+zip'></label><p id='form-status' role='status' aria-live='polite'></p><div class='actions'><button id='cancel' type='button' class='secondary'>Cancel</button><button id='save'>Save source</button></div></form></dialog></body></html>">>].
